function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
R = 8.314               ;
MWa = 104               ;
mwa = 205.7             ;
Tref = 355.382          ;
Tamb = 280.382          ;
V = 0.00567             ;
B1 = 0.193              ;
P = 1.594               ;
B2 = 0.167              ;
Cppa = 3.140            ;
Cpma = 1.675            ;
Cpwa = 4.18             ;
tb = 4000               ;
a1_ina = 0.000*7.5*0.001;
koa= 55                 ;
k1a = 1000              ;
k2a = 0.4               ;
Ea = 29560.888          ;
coa = 5.2e-5            ;
c1a = 16.44             ;
c2a = 2.3               ;
c3a = 1.563             ;
aoa = 555.556           ;
Hpa = -70152.16         ;
gma = 900               ;
gpa = 1040              ;
gwa = 1000              ;
doa = .814              ;
d1a = -5.13             ;
hf = 1/0.7              ;

y(1)=(x(2)/(x(1)+x(2)+ mwa)                                                                    );
y(2)=((coa*exp(c1a*y(1)))*10^(c2a*(aoa/x(3))-c3a)                                              );
y(3)=(koa*(exp(-Ea/(R*x(3))))*(k1a*y(2))^k2a                                                   );
y(4)=(x(1)/MWa                                                                                 );
y(5)=(1.2*y(3)*y(4)                                                                            );
y(6)=(((x(1)/gma) + (x(2)/gpa) + (mwa/gwa))*P/B1 + B2                                          );
y(7)=(0.5*(x(3)+u(1))                                                                          );
y(8)=((coa*exp(c1a*y(1)))*(10^(c2a*(aoa/y(7))-c3a))                                            );
y(9)=(doa*exp(d1a*y(8))                                                                        );
y(10)=(1.0/(1.0/y(9) + 1.0/hf)                                                                  );
y(11)=((( a1_ina*Cpma*(Tamb-x(3)) ) - ( y(9)*y(6)*(x(3)-u(1)) ) - ( V*(x(3)-Tamb) ) - y(5)*Hpa ));
y(12)=(( x(1)*Cpma + x(2)*Cppa + mwa*Cpwa )                                                     );

dx(1)=(a1_ina-y(5)*MWa)*tal;
dx(2)=(y(5)*MWa       )*tal;
dx(3)=(y(11)/y(12)    )*tal;
dx(4)=(( x(3)-Tref )^2)*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
